package com.worklink.controller; import com.worklink.entity.Category;import com.worklink.repository.CategoryRepository;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/categories") public class CategoryController {final CategoryRepository r;public CategoryController(CategoryRepository x){r=x;}@GetMapping public List<CategoryResponse> all(){return r.findAll().stream().map(x->new CategoryResponse(x.getId(),x.getName(),x.getDescription())).toList();}public record CategoryResponse(Long id,String name,String description){}}
